<template><form class="ops-form" @submit.prevent="save"><label>{{ $t('Status') }}<themed-select v-model="form.status" required><option v-for="status in statuses" :key="status" :value="status" :disabled="incident && status==='resolved' && !canResolve">{{ $t(status) }}</option></themed-select></label><label>{{ $t('Responsible operator ID') }}<themed-select v-if="incident" v-model="form.assigned_to"><option :value="null">{{ $t('Unassigned') }}</option><option v-for="op in operators" :key="op.id" :value="op.id">#{{ op.id }} · {{ op.name }}</option></themed-select><input v-else v-model="form.assigned_to" type="number" min="1" :placeholder="$t('Existing authorized operator only')"></label><label v-if="!incident">{{ $t('Service team') }}<themed-select v-model="form.team_id"><option :value="null">{{ $t('Unassigned') }}</option><option v-for="team in teams || []" :key="team.id" :value="team.id">{{ team.name }}</option></themed-select></label><label v-if="!incident">{{ $t('Priority') }}<themed-select v-model="form.priority"><option v-for="p in ['normal','high','urgent']" :key="p" :value="p">{{ $t(p) }}</option></themed-select></label><label>{{ $t('Due at (device time zone)') }}<input v-model="localDue" type="datetime-local" :required="incident"></label><label class="ops-wide">{{ $t('Action and evidence') }}<textarea v-model.trim="form.reason" minlength="5" maxlength="2000" required></textarea></label><p v-if="incident && !canResolve" class="ops-muted ops-wide">{{ $t('A fresh healthy sample after the last failure is required to close this incident.') }}</p><div class="ops-actions ops-wide"><button class="ops-primary" type="submit" :disabled="busy">{{ $t(busy?'Saving':'Save handling record') }}</button></div></form></template>
<script>
export default {props:{record:Object,url:String,incident:Boolean,canResolve:Boolean,operators:Array,teams:Array},data(){return {busy:false,localDue:'',form:{}}},computed:{statuses(){return this.incident?['open','acknowledged','investigating','resolved']:['open','following','resolved']}},watch:{record:{immediate:true,handler(){this.reset()}}},methods:{reset(){const r=this.record||{};this.form={request_key:crypto.randomUUID(),revision:r.revision||0,status:r.status||'open',priority:r.priority||'normal',assigned_to:r.assigned_to||null,team_id:r.team_id||null,reason:'',due_at:null};const raw=r.due_at;const d=raw?new Date(/^\d{4}-\d\d-\d\d \d\d:\d\d:\d\d$/.test(raw)?raw.replace(' ','T')+'Z':raw):null;this.localDue=d&&!isNaN(d.getTime())?new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16):''},save(){const payload={...this.form,assigned_to:this.form.assigned_to||null,due_at:this.localDue?new Date(this.localDue).toISOString():null};this.$inertia.post(this.url,payload,{preserveScroll:true,onStart:()=>this.busy=true,onSuccess:()=>this.reset(),onFinish:()=>this.busy=false})}}};
</script>
